# RW4DM_LAYER2: DupLayer, OneLayerOn, OneLayerOff: layers with their attributes and layer visibility. The script rw4dm_layer2_script.txt is generated by rw4dm_gen.py. The oracle is exact set / string logic on four objects (ids 1..4 = Point, Line, Plane, Box):
# after each step the objects that List reaches are compared, as id:kind:layer[:name], with the expected list exactly (and the printed message lines with their patterns).
RW4_LAYER2_OUT=""
if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
  RW4_LAYER2_OUT="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/rw4dm_layer2_script.txt" 2>&1)" || { echo "$RW4_LAYER2_OUT" | tail -40; echo "FAIL RW4DM_LAYER2_run: script exited non-zero"; fail=1; RW4_LAYER2_OUT=""; }
else
  RW4_LAYER2_OUT="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/rw4dm_layer2_script.txt" 2>&1)" || { echo "$RW4_LAYER2_OUT" | tail -40; echo "FAIL RW4DM_LAYER2_run: script exited non-zero"; fail=1; RW4_LAYER2_OUT=""; }
fi
rw4_layer2_block() { awk -v name="$1" '$0 ~ ("Unknown command: RW4BEGIN_" name "$") { on = 1; next } on && /Unknown command: RW4BEGIN_/ { exit } on { print }' <<<"$RW4_LAYER2_OUT"; }
# rw4_layer2_state STEP EXPECTED DESC [PATTERN...]: the objects listed in the step read exactly EXPECTED ("-" = none); each PATTERN must match a printed line of the step
rw4_layer2_state() {
  local blk got name desc pat bad want; name="$1"; want="$2"; desc="$3"; blk="$(rw4_layer2_block "$name")"
  got="$({ grep -E '^history: Object [0-9]+ \(' <<<"$blk" || true; } | sed -E "s/^history: Object ([0-9]+) \(([^)]*)\) layer (.*) name '(.*)'\$/\1:\2:\3:\4/; s/^history: Object ([0-9]+) \(([^)]*)\) layer (.*)\$/\1:\2:\3/" | tr '\n' ' ' | sed 's/ $//')"; [ -n "$got" ] || got="-"
  bad=""
  shift 3
  for pat in "$@"; do grep -qE "^history: $pat" <<<"$blk" || bad="$bad [$pat]"; done
  if [ "$got" = "$want" ] && [ -z "$bad" ]; then echo "ok   RW4DM_LAYER2_$name: $desc (objects: $got)"
  else echo "FAIL RW4DM_LAYER2_$name: $desc (listed '$got', expected '$want'; missing message patterns:${bad:- none})"; fail=1; { grep -E '^history: (Object|!|[A-Za-z]+:)' <<<"$blk" || true; } | head -14 | sed 's/^/     line: /'; fi
}
rw4_layer2_state move "1:point:A 2:curve:Default 3:surface:A 4:polysurface:Default" "ChangeLayer puts the point (1) and the plane (3) on layer A" 
rw4_layer2_state dup "1:point:A 2:curve:Default 3:surface:A 4:polysurface:Default 5:point:A2 6:surface:A2" "DupLayer Layer=A Name=A2 makes layer A2 with copies of the point and the plane (ids 5 and 6) and leaves A and its objects alone" "DupLayer: A -> A2 with 2 object\(s\)"
rw4_layer2_state dup_empty "1:point:A 2:curve:Default 3:surface:A 4:polysurface:Default 5:point:A2 6:surface:A2" "DupLayer Layer=A Name=A3 Objects=No makes the layer without copying any object (and the new layer exists: SetLayer finds it)" "DupLayer: A -> A3 with 0 object\(s\)" "Current layer: A3"
rw4_layer2_state dup_locked "2:curve:Default 4:polysurface:Default 5:point:A2 6:surface:A2" "a locked layer is duplicated with its attributes: after LayerLock A, DupLayer Layer=A Name=A4 gives a locked A4 whose copies (7 and 8) cannot be selected, like 1 and 3 on A" "DupLayer: A -> A4 with 2 object\(s\)"
rw4_layer2_state unlock "1:point:A 2:curve:Default 3:surface:A 4:polysurface:Default 5:point:A2 6:surface:A2 7:point:A4 8:surface:A4" "LayerUnlock makes A and A4 selectable again: all eight objects" 
rw4_layer2_state on_one "2:curve:Default 4:polysurface:Default" "OneLayerOn with the line (2, on Default) selected: only its layer stays on, SelAll reaches only objects on Default (2 and 4)" "OneLayerOn: 1 layer\(s\) on, all others off"
rw4_layer2_state all_on "1:point:A 2:curve:Default 3:surface:A 4:polysurface:Default 5:point:A2 6:surface:A2 7:point:A4 8:surface:A4" "AllLayersOn brings every layer back" 
rw4_layer2_state on_two "1:point:A 3:surface:A 5:point:A2 6:surface:A2" "OneLayerOn with objects 1 (layer A) and 5 (layer A2) selected keeps exactly A and A2 on" "OneLayerOn: 2 layer\(s\) on, all others off"
rw4_layer2_state off_sel "1:point:A 2:curve:Default 3:surface:A 4:polysurface:Default 5:point:A2 6:surface:A2" "OneLayerOff with object 7 (layer A4) selected turns A4 off: after AllLayersOn the other layers are on, A4 is not (SelAll: all but 7 and 8)" "OneLayerOff: 1 layer\(s\) turned off"
rw4_layer2_state off_current "1:point:A 2:curve:Default 3:surface:A 4:polysurface:Default 7:point:A4 8:surface:A4" "OneLayerOff with nothing selected turns off the current layer (A2): SelAll then misses 5 and 6" 
